import {courseOptions,holeDetails,groupProgress,guidance} from './round-experience-model.js';
import {createCourseMap} from './course-map.js';
const $=s=>document.querySelector(s);
let course=courseOptions[0],hole=3,selected=8,minute=0,scenario='normal',view='hole',playing=false,started=false,ended=false,timer,noticeTimer,geo=null;
const film=$('#film'),rows=new Map(),dots=new Map();
$('#course').replaceChildren(...courseOptions.map(c=>{const o=document.createElement('option');o.value=c.id;o.textContent=c.name;return o;}));
for(let i=1;i<=18;i++){const b=document.createElement('button');b.textContent=String(i).padStart(2,'0');b.dataset.hole=i;b.setAttribute('aria-label','Explore hole '+i);b.onclick=()=>setHole(i);$('#hole-buttons').append(b);}
for(let id=4;id<=12;id++){const dot=document.createElement('button');dot.className='progress-dot';dot.textContent=String(id).padStart(2,'0');dot.setAttribute('aria-label','Select demo group '+id);dot.onclick=()=>selectGroup(id);$('#progress-track').append(dot);dots.set(id,dot);const row=document.createElement('button');row.className='group-row';const label=document.createElement('span'),name=document.createElement('span'),detail=document.createElement('small'),state=document.createElement('span');name.textContent=id===8?'Group 08 · Your group':'Group '+String(id).padStart(2,'0');label.append(name,detail);row.append(label,state);row.onclick=()=>selectGroup(id);$('#group-list').append(row);rows.set(id,{row,detail,state});}
function notify(text){$('#notice').textContent=text;$('#notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').hidden=true,4000);}
function selectGroup(id){selected=id;setHole(groupProgress(id,minute,scenario).hole);}
function setHole(value){hole=Math.max(1,Math.min(18,value));const d=holeDetails(course,hole);for(const b of $('#hole-buttons').children)b.setAttribute('aria-pressed',String(+b.dataset.hole===hole));$('#previous').disabled=hole===1;$('#next').disabled=hole===18;$('#hole-label').textContent='Hole '+String(hole).padStart(2,'0');$('#hero-meta').textContent=d.par?`HOLE ${hole} · PAR ${d.par} · ${d.yards} YARDS · ${d.tees.toUpperCase()}`:`HOLE ${hole} · DETAILS NOT CONFIGURED`;$('#hero-title').textContent=course.name;$('#hole-image').hidden=!d.photo;$('#no-media').hidden=!!d.photo;if(d.photo){$('#hole-image').src=d.photo;$('#hole-image').alt=`${course.name}, hole ${hole}, aerial image`;}film.pause();film.removeAttribute('src');film.load();film.poster=d.photo||'';$('#flight-scrub').value=0;if(view==='flight')loadFilm();update();}
function loadFilm(){const d=holeDetails(course,hole);if(!d.video){$('#film-status').textContent='Flyover footage is not configured for this course.';return;}if(film.getAttribute('src')!==d.video){film.src=d.video;film.load();$('#film-status').textContent='Loading selected hole…';}}
function showView(next){view=next;for(const key of ['hole','map','flight'])$('#'+key+'-view').hidden=key!==view;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.view===view)));$('#view-caption').textContent={hole:'COURSE IMAGE · NOT A GPS MAP',map:'REAL GEOGRAPHY · DEVICE GPS',flight:'EXISTING COURSE FLYOVER'}[view];$('#visual-note').textContent={hole:'Hole imagery is not geographically calibrated. Group progress is shown separately, not placed over the photograph.',map:'Approximate course-area center. No geographic hole boundaries or other golfers are connected. Blue marker = your device only.',flight:'Explore the existing footage with playback or the scrubber. This footage does not show live golfers.'}[view];if(view!=='flight')film.pause();if(view==='flight')loadFilm();if(view==='map'){if(!geo){if(!window.L){$('#gps-status').textContent='Map library unavailable. Hole images and flyovers still work.';return;}geo=createCourseMap($('#geographic-map'),{L:window.L,onStatus:text=>$('#gps-status').textContent=text});geo.setCourse(course);}requestAnimationFrame(()=>geo.resize());}}
function update(){const g=guidance(scenario),own=groupProgress(8,minute,scenario),finish=510+course.target+(scenario==='queue'?18:scenario==='gap'?10:0),clock=n=>`${String(Math.floor(n/60)%24).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;$('#pace-label').textContent=ended?'Round ended':g.label;$('#pace-label').dataset.state=scenario;$('#brief-title').textContent=g.title;$('#brief-copy').textContent=g.text;$('#your-hole').textContent=String(own.hole).padStart(2,'0')+' / 18';$('#finish').textContent=clock(finish-7)+'–'+clock(finish+8);$('#traffic-title').textContent='Hole '+String(hole).padStart(2,'0')+' traffic';let count=0;for(const [id,{row,detail,state}] of rows){const p=groupProgress(id,minute,scenario),visible=p.hole===hole,dot=dots.get(id);row.hidden=dot.hidden=!visible;if(visible)count++;dot.style.left=(6+p.fraction*88)+'%';dot.classList.toggle('stale',p.stale);dot.setAttribute('aria-pressed',String(selected===id));row.setAttribute('aria-pressed',String(selected===id));detail.textContent=p.stale?'Frozen last observation':`Hole ${p.hole} · ${Math.round(p.fraction*100)}% demo progress`;state.textContent=selected===id?'Selected':'View →';}const p=groupProgress(selected,minute,scenario);$('#selected-detail').textContent=(count?'':'No demo groups on this hole. ')+`Selected: Group ${String(selected).padStart(2,'0')} · hole ${p.hole} · ${p.stale?'last observation, not live':'simulated progress'}. No live location is inferred from this image.`;$('#timeline-label').textContent=minute+' simulated minutes';if(document.activeElement!==$('#timeline'))$('#timeline').value=minute;$('#play').textContent=playing?'Ⅱ Pause demo':'▷ Play demo';$('#start-round').textContent=ended?'Start again':started?'End demo':'Start demo ↗';$('#reward-result').textContent=ended?(scenario==='normal'||scenario==='queue'?'SIMULATED $5 CREDIT · NO MONEY ISSUED':'STAFF REVIEW · NO CREDIT ISSUED'):'DEMO ONLY · NO MONEY ISSUED';}
function pause(){playing=false;clearInterval(timer);}
$('#course').onchange=e=>{pause();geo?.stopGPS();course=courseOptions.find(c=>c.id===e.target.value);minute=0;scenario='normal';started=false;ended=false;$('#scenario').value='normal';$('#region').textContent=course.region.toUpperCase();$('#course-title').textContent=course.name;geo?.setCourse(course);setHole(3);if(!course.media)showView('map');};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('#previous').onclick=()=>setHole(hole-1);$('#next').onclick=()=>setHole(hole+1);$('#my-group').onclick=()=>selectGroup(8);
$('#scenario').onchange=e=>{scenario=e.target.value;update();notify(guidance(scenario).text);};$('#timeline').oninput=e=>{minute=+e.target.value;update();};$('#step').onclick=()=>{if(ended)return;minute=Math.min(140,minute+5);update();};$('#play').onclick=()=>{if(ended){notify('Start another demo round to continue.');return;}if(playing)pause();else{started=true;playing=true;timer=setInterval(()=>{minute=Math.min(140,minute+1);if(minute===140)pause();update();},1000);}update();};$('#start-round').onclick=()=>{if(ended){ended=false;started=true;minute=0;scenario='normal';$('#scenario').value='normal';}else if(started){pause();ended=true;geo?.stopGPS();notify('Demo round ended. Reward results are simulated; no credit was issued.');}else started=true;update();};$('#reset').onclick=()=>{pause();geo?.stopGPS();minute=0;started=false;ended=false;scenario='normal';selected=8;$('#scenario').value='normal';setHole(3);};
$('#overview').onclick=()=>geo?.overview();$('#gps').onclick=()=>{if(!window.isSecureContext){notify('GPS requires HTTPS or localhost.');return;}geo?.startGPS();};$('#stop-gps').onclick=()=>geo?.stopGPS();
film.onloadedmetadata=()=>$('#film-status').textContent='Drag the scrubber or press play to explore this hole.';film.onerror=()=>$('#film-status').textContent='Footage could not load. The hole image remains available.';film.ontimeupdate=()=>{if(Number.isFinite(film.duration)&&document.activeElement!==$('#flight-scrub'))$('#flight-scrub').value=film.currentTime/film.duration*100;};$('#flight-scrub').oninput=e=>{if(Number.isFinite(film.duration)){film.pause();film.currentTime=film.duration*(+e.target.value/100);}};
$('#hole-image').onerror=()=>{$('#hole-image').hidden=true;$('#no-media').hidden=false;};window.addEventListener('pagehide',()=>{pause();film.pause();geo?.stopGPS();});setInterval(()=>{if(view==='map'&&geo)$('#gps-status').textContent=geo.status();},10000);
setHole(3);showView('hole');
